"use strict";

const assert = require("node:assert/strict");
const http = require("node:http");
const test = require("node:test");
const { createVroidOauthServer, hostAllowed, OAUTH_CALLBACK_PATH } = require("./vroid-oauth-server.cjs");

function request(port, path, { host } = {}) {
  return new Promise((resolve, reject) => {
    const req = http.request(
      {
        host: "127.0.0.1",
        port,
        path,
        method: "GET",
        headers: host ? { host } : undefined,
      },
      (response) => {
        const chunks = [];
        response.on("data", (chunk) => chunks.push(chunk));
        response.on("end", () =>
          resolve({
            status: response.statusCode,
            body: Buffer.concat(chunks).toString("utf8"),
          }),
        );
      },
    );
    req.on("error", reject);
    req.end();
  });
}

async function startServer(context, onOauthCallback) {
  const server = createVroidOauthServer({ port: 0, onOauthCallback });
  const address = await server.listen();
  context.after(() => server.close());
  return address.port;
}

test("hostAllowed only accepts bare loopback hosts", () => {
  assert.equal(hostAllowed("127.0.0.1:47901"), true);
  assert.equal(hostAllowed("localhost:47901"), true);
  assert.equal(hostAllowed("evil.example:47901"), false);
  assert.equal(hostAllowed("127.0.0.1:47901@evil.example"), false);
  assert.equal(hostAllowed(""), false);
  assert.equal(hostAllowed(undefined), false);
});

test("parses code/state from the callback URL and returns a success page", async (context) => {
  let received = null;
  const port = await startServer(context, async (params) => {
    received = params;
  });

  const { status, body } = await request(
    port,
    `${OAUTH_CALLBACK_PATH}?code=auth-code&state=abc123`,
  );

  assert.equal(status, 200);
  assert.match(body, /connected/i);
  assert.deepEqual(received, { code: "auth-code", state: "abc123", error: null });
});

test("returns a failure page and does not throw when the callback handler rejects", async (context) => {
  const port = await startServer(context, async () => {
    throw new Error("state mismatch");
  });

  const { status, body } = await request(port, `${OAUTH_CALLBACK_PATH}?error=access_denied`);

  assert.equal(status, 200);
  assert.match(body, /sign-in failed/i);
});

test("404s on any path other than the callback route", async (context) => {
  const port = await startServer(context, async () => {});

  const { status } = await request(port, "/not-the-callback");
  assert.equal(status, 404);
});

test("rejects requests with a non-loopback Host header", async (context) => {
  const port = await startServer(context, async () => {});

  const { status } = await request(port, `${OAUTH_CALLBACK_PATH}?code=x&state=y`, {
    host: "evil.example",
  });
  assert.equal(status, 403);
});

"use strict";

const assert = require("node:assert/strict");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const test = require("node:test");
const { createVroidHubAuth } = require("./vroid-hub-auth.cjs");

function fixture(context) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "avatar-vroid-auth-"));
  context.after(() => fs.rmSync(root, { force: true, recursive: true }));
  return { authFilePath: path.join(root, "vroid-hub-auth.json") };
}

// Not real encryption, just proves the store actually transforms bytes and
// round-trips through the injected callbacks rather than assuming identity.
function hexCodec() {
  return {
    encrypt: (buffer) => Buffer.from(buffer.toString("hex")),
    decrypt: (buffer) => Buffer.from(buffer.toString(), "hex"),
  };
}

function fakeFetch(handler) {
  const calls = [];
  const fetchImpl = async (url, init) => {
    const params = new URLSearchParams(init.body);
    calls.push({ url, headers: init.headers, params });
    return handler(params, url);
  };
  fetchImpl.calls = calls;
  return fetchImpl;
}

function jsonResponse(status, body) {
  return { ok: status >= 200 && status < 300, status, json: async () => body };
}

function createAuth(context, overrides = {}) {
  const { authFilePath } = fixture(context);
  const { encrypt, decrypt } = hexCodec();
  return createVroidHubAuth({
    clientId: "client-123",
    clientSecret: "secret-456",
    redirectUri: "http://127.0.0.1:47901/vroid-oauth-callback",
    authFilePath,
    encrypt,
    decrypt,
    ...overrides,
  });
}

test("builds an authorize URL with PKCE and state", (context) => {
  const auth = createAuth(context, { fetchImpl: async () => jsonResponse(200, {}) });
  const url = new URL(auth.buildAuthorizeUrl());

  assert.equal(url.origin + url.pathname, "https://hub.vroid.com/oauth/authorize");
  assert.equal(url.searchParams.get("response_type"), "code");
  assert.equal(url.searchParams.get("client_id"), "client-123");
  assert.equal(
    url.searchParams.get("redirect_uri"),
    "http://127.0.0.1:47901/vroid-oauth-callback",
  );
  assert.equal(url.searchParams.get("scope"), "default heart");
  assert.equal(url.searchParams.get("code_challenge_method"), "S256");
  assert.ok(url.searchParams.get("state"));
  assert.ok(url.searchParams.get("code_challenge"));
  assert.equal(auth.isConnected(), false);
});

test("completes sign-in and persists encrypted tokens that survive a reload", async (context) => {
  const { authFilePath } = fixture(context);
  const { encrypt, decrypt } = hexCodec();
  const fetchImpl = fakeFetch((params) => {
    assert.equal(params.get("grant_type"), "authorization_code");
    assert.equal(params.get("client_secret"), "secret-456");
    assert.equal(params.get("code"), "auth-code");
    return jsonResponse(200, {
      access_token: "access-1",
      refresh_token: "refresh-1",
      token_type: "Bearer",
      expires_in: 3600,
    });
  });
  const auth = createVroidHubAuth({
    clientId: "client-123",
    clientSecret: "secret-456",
    redirectUri: "http://127.0.0.1:47901/vroid-oauth-callback",
    authFilePath,
    encrypt,
    decrypt,
    fetchImpl,
  });
  const url = new URL(auth.buildAuthorizeUrl());
  const state = url.searchParams.get("state");

  await auth.exchangeCode("auth-code", state);

  assert.equal(auth.isConnected(), true);
  const token = await auth.getValidAccessToken();
  assert.deepEqual(token, { accessToken: "access-1", tokenType: "Bearer" });

  const onDisk = fs.readFileSync(authFilePath, "utf8");
  assert.equal(onDisk.includes("access-1"), false, "token must not be stored in plaintext");

  const reloaded = createVroidHubAuth({
    clientId: "client-123",
    clientSecret: "secret-456",
    redirectUri: "http://127.0.0.1:47901/vroid-oauth-callback",
    authFilePath,
    encrypt,
    decrypt,
    fetchImpl: async () => jsonResponse(500, {}),
  });
  assert.equal(reloaded.isConnected(), true);
  assert.deepEqual(await reloaded.getValidAccessToken(), {
    accessToken: "access-1",
    tokenType: "Bearer",
  });
});

test("rejects exchanging a code with no pending flow or a mismatched state", async (context) => {
  const auth = createAuth(context, { fetchImpl: async () => jsonResponse(200, {}) });

  await assert.rejects(() => auth.exchangeCode("code", "some-state"), /no pending/i);

  const url = new URL(auth.buildAuthorizeUrl());
  const state = url.searchParams.get("state");
  await assert.rejects(() => auth.exchangeCode("code", `not-${state}`), /state/i);
  assert.equal(auth.isConnected(), false);
});

test("surfaces a failed token exchange without persisting anything", async (context) => {
  const { authFilePath } = fixture(context);
  const auth = createAuth(context, {
    fetchImpl: async () => jsonResponse(400, { error: "invalid_grant" }),
  });
  const url = new URL(auth.buildAuthorizeUrl());
  const state = url.searchParams.get("state");

  await assert.rejects(() => auth.exchangeCode("bad-code", state), /sign-in failed/i);
  assert.equal(auth.isConnected(), false);
  assert.equal(fs.existsSync(authFilePath), false);
});

test("refreshes an access token automatically once it is close to expiring", async (context) => {
  let call = 0;
  const fetchImpl = fakeFetch((params) => {
    call += 1;
    if (call === 1) {
      assert.equal(params.get("grant_type"), "authorization_code");
      return jsonResponse(200, {
        access_token: "access-1",
        refresh_token: "refresh-1",
        token_type: "Bearer",
        expires_in: 0,
      });
    }
    assert.equal(params.get("grant_type"), "refresh_token");
    assert.equal(params.get("refresh_token"), "refresh-1");
    return jsonResponse(200, {
      access_token: "access-2",
      refresh_token: "refresh-2",
      token_type: "Bearer",
      expires_in: 3600,
    });
  });
  const auth = createAuth(context, { fetchImpl });
  const url = new URL(auth.buildAuthorizeUrl());
  await auth.exchangeCode("auth-code", url.searchParams.get("state"));

  const token = await auth.getValidAccessToken();
  assert.equal(token.accessToken, "access-2");
  assert.equal(call, 2);
});

test("clears the persisted session on disconnect", async (context) => {
  const { authFilePath } = fixture(context);
  const { encrypt, decrypt } = hexCodec();
  const fetchImpl = async () =>
    jsonResponse(200, {
      access_token: "access-1",
      refresh_token: "refresh-1",
      token_type: "Bearer",
      expires_in: 3600,
    });
  const auth = createVroidHubAuth({
    clientId: "client-123",
    clientSecret: "secret-456",
    redirectUri: "http://127.0.0.1:47901/vroid-oauth-callback",
    authFilePath,
    encrypt,
    decrypt,
    fetchImpl,
  });
  const url = new URL(auth.buildAuthorizeUrl());
  await auth.exchangeCode("auth-code", url.searchParams.get("state"));
  assert.equal(auth.isConnected(), true);

  auth.disconnect();

  assert.equal(auth.isConnected(), false);
  assert.equal(fs.existsSync(authFilePath), false);
  await assert.rejects(() => auth.getValidAccessToken(), /not connected/i);

  const reloaded = createVroidHubAuth({
    clientId: "client-123",
    clientSecret: "secret-456",
    redirectUri: "http://127.0.0.1:47901/vroid-oauth-callback",
    authFilePath,
    encrypt,
    decrypt,
    fetchImpl,
  });
  assert.equal(reloaded.isConnected(), false);
});

"use strict";

const assert = require("node:assert/strict");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const test = require("node:test");
const {
  clearVroidHubCredentials,
  readVroidHubCredentials,
  writeVroidHubCredentials,
} = require("./vroid-hub-credentials.cjs");

function fixture(context) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "avatar-vroid-creds-"));
  context.after(() => fs.rmSync(root, { force: true, recursive: true }));
  return path.join(root, "vroid-hub-credentials.json");
}

// Not real encryption, just proves the store actually transforms bytes and
// round-trips through the injected callbacks rather than assuming identity.
function hexCodec() {
  return {
    encrypt: (buffer) => Buffer.from(buffer.toString("hex")),
    decrypt: (buffer) => Buffer.from(buffer.toString(), "hex"),
  };
}

test("round-trips client id and secret through encrypt/decrypt", (context) => {
  const credentialsFilePath = fixture(context);
  const { encrypt, decrypt } = hexCodec();

  writeVroidHubCredentials(
    { credentialsFilePath, encrypt },
    { clientId: "client-123", clientSecret: "secret-456" },
  );

  const raw = JSON.parse(fs.readFileSync(credentialsFilePath, "utf8"));
  assert.equal(typeof raw.encrypted, "string");
  assert.doesNotMatch(raw.encrypted, /client-123|secret-456/);

  const read = readVroidHubCredentials({ credentialsFilePath, decrypt });
  assert.deepEqual(read, { clientId: "client-123", clientSecret: "secret-456" });
});

test("trims whitespace around client id and secret", (context) => {
  const credentialsFilePath = fixture(context);
  const { encrypt, decrypt } = hexCodec();

  writeVroidHubCredentials(
    { credentialsFilePath, encrypt },
    { clientId: "  client-123  ", clientSecret: "  secret-456  " },
  );

  assert.deepEqual(readVroidHubCredentials({ credentialsFilePath, decrypt }), {
    clientId: "client-123",
    clientSecret: "secret-456",
  });
});

test("rejects a blank client id or secret", (context) => {
  const credentialsFilePath = fixture(context);
  const { encrypt } = hexCodec();

  assert.throws(() =>
    writeVroidHubCredentials(
      { credentialsFilePath, encrypt },
      { clientId: "", clientSecret: "secret-456" },
    ),
  );
  assert.throws(() =>
    writeVroidHubCredentials(
      { credentialsFilePath, encrypt },
      { clientId: "client-123", clientSecret: "   " },
    ),
  );
  assert.throws(() =>
    writeVroidHubCredentials(
      { credentialsFilePath, encrypt },
      { clientId: undefined, clientSecret: "secret-456" },
    ),
  );
});

test("returns null when no credentials file exists", (context) => {
  const credentialsFilePath = fixture(context);
  const { decrypt } = hexCodec();
  assert.equal(readVroidHubCredentials({ credentialsFilePath, decrypt }), null);
});

test("returns null for a corrupt or malformed file", (context) => {
  const credentialsFilePath = fixture(context);
  const { decrypt } = hexCodec();

  fs.mkdirSync(path.dirname(credentialsFilePath), { recursive: true });
  fs.writeFileSync(credentialsFilePath, "not json");
  assert.equal(readVroidHubCredentials({ credentialsFilePath, decrypt }), null);

  fs.writeFileSync(credentialsFilePath, JSON.stringify({ encrypted: 42 }));
  assert.equal(readVroidHubCredentials({ credentialsFilePath, decrypt }), null);

  fs.writeFileSync(
    credentialsFilePath,
    JSON.stringify({ encrypted: Buffer.from("{}").toString("hex") }),
  );
  assert.equal(readVroidHubCredentials({ credentialsFilePath, decrypt }), null);
});

test("clearVroidHubCredentials removes the file and is idempotent", (context) => {
  const credentialsFilePath = fixture(context);
  const { encrypt, decrypt } = hexCodec();

  writeVroidHubCredentials(
    { credentialsFilePath, encrypt },
    { clientId: "client-123", clientSecret: "secret-456" },
  );
  assert.ok(fs.existsSync(credentialsFilePath));

  clearVroidHubCredentials({ credentialsFilePath });
  assert.equal(fs.existsSync(credentialsFilePath), false);
  assert.equal(readVroidHubCredentials({ credentialsFilePath, decrypt }), null);

  // Calling again on an already-absent file must not throw.
  clearVroidHubCredentials({ credentialsFilePath });
});

"use strict";

const assert = require("node:assert/strict");
const http = require("node:http");
const test = require("node:test");
const { Client } = require("@modelcontextprotocol/sdk/client/index.js");
const {
  StreamableHTTPClientTransport,
} = require("@modelcontextprotocol/sdk/client/streamableHttp.js");
const { MCP_PATH, createAgentBusServer } = require("./agent-bus.cjs");

// Same resolver the bus itself uses, loaded the way main.cjs loads it.
const resolverReady = import("../src/lib/stageCommands.js");

const CONTEXT = {
  animationCatalog: [
    { id: "vrma-03", label: "Peace Sign", source: "vrma", vrmaUrl: "/peace.vrma" },
    { id: "default", label: "Default", source: "sequence", sequence: ["vrma-03"] },
  ],
  avatarIds: ["avatar1", "avatar2"],
  environmentIds: ["env-forest"],
  audioSourceIds: ["system"],
};

const STATE = {
  runtime: { version: "9.9.9", mode: "desktop" },
  animations: [{ id: "vrma-03", label: "Peace Sign", playableOnce: true }],
  avatars: [{ id: "avatar1" }, { id: "avatar2" }],
  environments: [{ id: "env-forest", label: "Forest" }],
  audioSources: [{ id: "system", label: "Device output" }],
  current: { animationId: "default", avatarId: "avatar1" },
};

/**
 * @param {import('node:test').TestContext} context
 * @param {{ state?: unknown, token?: string | null }} [options]
 */
async function startServer(context, { state = STATE, token = null } = {}) {
  const { resolveStageCommand } = await resolverReady;
  const applied = [];
  const server = createAgentBusServer({
    port: 0,
    version: "9.9.9",
    resolveCommand: resolveStageCommand,
    getContext: () => CONTEXT,
    getState: () => state,
    applyAction: (action) => applied.push(action),
    getToken: () => token,
  });
  const address = await server.listen();
  context.after(() => server.close());
  return { port: address.port, applied };
}

/**
 * @param {import('node:test').TestContext} context
 * @param {number} port
 * @param {string | null} [token]
 */
async function connect(context, port, token = null) {
  const client = new Client({ name: "test", version: "0.0.0" });
  const transport = new StreamableHTTPClientTransport(
    new URL(`http://127.0.0.1:${port}${MCP_PATH}`),
    token ? { requestInit: { headers: { authorization: `Bearer ${token}` } } } : undefined,
  );
  await client.connect(transport);
  context.after(() => client.close());
  return client;
}

/** The tool result's JSON payload, whichever half of the result carries it. */
function payload(result) {
  if (result.structuredContent) return result.structuredContent;
  return JSON.parse(result.content[0].text);
}

/**
 * @param {number} port
 * @param {{ method?: string, headers?: Record<string, string>, body?: string }} [options]
 */
function raw(port, { method = "POST", headers = {}, body } = {}) {
  return new Promise((resolve, reject) => {
    const outgoing = { "content-type": "application/json", accept: "application/json, text/event-stream", ...headers };
    if (body !== undefined) outgoing["content-length"] = String(Buffer.byteLength(body));
    const request = http.request(
      { host: "127.0.0.1", port, path: MCP_PATH, method, headers: outgoing },
      (response) => {
        const chunks = [];
        response.on("data", (chunk) => chunks.push(chunk));
        response.on("end", () =>
          resolve({ status: response.statusCode, body: Buffer.concat(chunks).toString("utf8") }),
        );
      },
    );
    request.on("error", reject);
    if (body !== undefined) request.write(body);
    request.end();
  });
}

test("advertises the agent-facing tool surface", async (t) => {
  const { port } = await startServer(t);
  const client = await connect(t, port);

  const names = (await client.listTools()).tools.map((tool) => tool.name).sort();
  assert.deepEqual(names, [
    "get_status",
    "list_stage",
    "play_animation",
    "set_avatar",
    "set_environment",
    "stop_animation",
  ]);
});

test("does not expose the audio source, which is the user's setting", async (t) => {
  const { port } = await startServer(t);
  const client = await connect(t, port);

  const names = (await client.listTools()).tools.map((tool) => tool.name);
  assert.equal(
    names.some((name) => name.includes("audio")),
    false,
  );
});

test("play_animation plays once by default rather than changing the selection", async (t) => {
  const { port, applied } = await startServer(t);
  const client = await connect(t, port);

  const result = await client.callTool({
    name: "play_animation",
    arguments: { animation: "vrma-03" },
  });

  assert.equal(result.isError ?? false, false);
  assert.deepEqual(applied, [{ kind: "animation.play", animationId: "vrma-03", mode: "once" }]);
});

test("play_animation persists the selection only when asked", async (t) => {
  const { port, applied } = await startServer(t);
  const client = await connect(t, port);

  await client.callTool({
    name: "play_animation",
    arguments: { animation: "vrma-03", persist: true },
  });

  assert.deepEqual(applied, [{ kind: "animation.play", animationId: "vrma-03", mode: "select" }]);
});

test("play_animation accepts a label and reports the id it became", async (t) => {
  const { port, applied } = await startServer(t);
  const client = await connect(t, port);

  const result = await client.callTool({
    name: "play_animation",
    arguments: { animation: "Peace Sign" },
  });

  assert.equal(applied[0].animationId, "vrma-03");
  assert.equal(payload(result).action.animationId, "vrma-03");
});

test("a refused command is a tool error carrying a way out", async (t) => {
  const { port, applied } = await startServer(t);
  const client = await connect(t, port);

  const result = await client.callTool({
    name: "play_animation",
    arguments: { animation: "Peace Sing" },
  });

  assert.equal(result.isError, true);
  assert.match(result.content[0].text, /No animation matches/);
  assert.match(result.content[0].text, /list_stage/);
  assert.deepEqual(applied, []);
});

test("a looping sequence cannot be played once, and says what to do instead", async (t) => {
  const { port } = await startServer(t);
  const client = await connect(t, port);

  const result = await client.callTool({
    name: "play_animation",
    arguments: { animation: "default" },
  });

  assert.equal(result.isError, true);
  assert.match(result.content[0].text, /persist: true/);
});

test("set_environment takes each of the three shapes", async (t) => {
  const { port, applied } = await startServer(t);
  const client = await connect(t, port);

  await client.callTool({ name: "set_environment", arguments: { type: "env", id: "env-forest" } });
  await client.callTool({ name: "set_environment", arguments: { type: "color", color: "#e9e1fa" } });
  await client.callTool({ name: "set_environment", arguments: { type: "none" } });

  assert.deepEqual(
    applied.map((action) => action.selection),
    [{ type: "env", id: "env-forest" }, { type: "color", value: "#e9e1fa" }, { type: "none" }],
  );
});

test("set_avatar refuses an id this install does not have", async (t) => {
  const { port, applied } = await startServer(t);
  const client = await connect(t, port);

  const result = await client.callTool({ name: "set_avatar", arguments: { avatar: "avatar9" } });

  assert.equal(result.isError, true);
  assert.deepEqual(applied, []);
});

test("list_stage hands over the same catalog /v1/state does", async (t) => {
  const { port } = await startServer(t);
  const client = await connect(t, port);

  const result = await client.callTool({ name: "list_stage", arguments: {} });

  assert.deepEqual(payload(result), STATE);
});

test("before the window reports, list_stage refuses and get_status still answers", async (t) => {
  const { port } = await startServer(t, { state: null });
  const client = await connect(t, port);

  const listed = await client.callTool({ name: "list_stage", arguments: {} });
  assert.equal(listed.isError, true);
  assert.match(listed.content[0].text, /still starting up/);

  const status = await client.callTool({ name: "get_status", arguments: {} });
  assert.equal(status.isError ?? false, false);
  assert.equal(payload(status).ready, false);
});

test("the token gate is the bus's, not a second one", async (t) => {
  const { port } = await startServer(t, { token: "secret-token" });

  await assert.rejects(() => connect(t, port));

  const client = await connect(t, port, "secret-token");
  assert.equal((await client.listTools()).tools.length, 6);
});

test("a stateless endpoint turns away the GET and DELETE of older revisions", async (t) => {
  const { port } = await startServer(t);

  for (const method of ["GET", "DELETE"]) {
    const response = await raw(port, { method });
    assert.equal(response.status, 405, method);
    assert.equal(JSON.parse(response.body).error.message, "This MCP endpoint is stateless: use POST.");
  }
});

test("a web page is refused here too, in the shape MCP speaks", async (t) => {
  const { port } = await startServer(t);

  const response = await raw(port, {
    headers: { origin: "http://localhost:5173" },
    body: JSON.stringify({ jsonrpc: "2.0", id: 1, method: "tools/list" }),
  });

  assert.equal(response.status, 403);
  const body = JSON.parse(response.body);
  assert.equal(body.jsonrpc, "2.0");
  assert.match(body.error.message, /web page/);
});

test("malformed JSON is a parse error, not a stage error", async (t) => {
  const { port } = await startServer(t);

  const response = await raw(port, { body: "{ not json" });

  assert.equal(response.status, 400);
  assert.equal(JSON.parse(response.body).error.code, -32700);
});

"use strict";

const assert = require("node:assert/strict");
const http = require("node:http");
const test = require("node:test");
const WebSocket = require("ws");
const {
  COMMAND_PATH,
  SOCKET_PATH,
  STATE_PATH,
  createAgentBusServer,
  hostAllowed,
} = require("./agent-bus.cjs");

// The renderer's own resolver, loaded exactly the way main.cjs loads it. If
// that import ever stops working from CommonJS, these tests are where it shows.
const resolverReady = import("../src/lib/stageCommands.js");

const CONTEXT = {
  animationCatalog: [
    { id: "vrma-03", label: "Peace Sign", source: "vrma", vrmaUrl: "/peace.vrma" },
    { id: "default", label: "Default", source: "sequence", sequence: ["vrma-03"] },
  ],
  avatarIds: ["avatar1", "avatar2"],
  environmentIds: ["env-forest"],
  audioSourceIds: ["system", "microphone"],
};

const STATE = {
  animations: [{ id: "vrma-03", label: "Peace Sign", playableOnce: true }],
  avatars: [{ id: "avatar1" }],
};

/**
 * @param {import('node:test').TestContext} context
 * @param {{ stageContext?: unknown, state?: unknown, token?: string | null }} [options]
 */
async function startServer(context, { stageContext = CONTEXT, state = STATE, token = null } = {}) {
  const { resolveStageCommand } = await resolverReady;
  const applied = [];
  const server = createAgentBusServer({
    port: 0,
    resolveCommand: resolveStageCommand,
    getContext: () => stageContext,
    getState: () => state,
    applyAction: (action) => applied.push(action),
    getToken: () => token,
  });
  const address = await server.listen();
  context.after(() => server.close());
  return { port: address.port, applied };
}

/**
 * @param {number} port
 * @param {{ method?: string, path?: string, body?: string,
 *   headers?: Record<string, string> }} [options]
 */
function request(port, { method = "POST", path = COMMAND_PATH, body, headers = {} } = {}) {
  return new Promise((resolve, reject) => {
    const outgoing = {
      "content-type": "application/json",
      ...headers,
    };
    if (body !== undefined && outgoing["content-length"] === undefined) {
      outgoing["content-length"] = String(Buffer.byteLength(body));
    }

    const req = http.request({ host: "127.0.0.1", port, path, method, headers: outgoing }, (response) => {
      const chunks = [];
      response.on("data", (chunk) => chunks.push(chunk));
      response.on("end", () => {
        const text = Buffer.concat(chunks).toString("utf8");
        let json = null;
        try {
          json = JSON.parse(text);
        } catch {
          // A few paths answer with no body at all.
        }
        resolve({ status: response.statusCode, body: json, text });
      });
    });
    req.on("error", reject);
    if (body !== undefined) req.write(body);
    req.end();
  });
}

/** @param {number} port */
function command(port, payload, options = {}) {
  return request(port, { body: JSON.stringify(payload), ...options });
}

