import * as THREE from 'three';

/** @typedef {'loop' | 'once'} AnimationPlayback */

/**
 * @param {THREE.AnimationAction} action
 * @param {AnimationPlayback} playback
 */
export function configureAnimationAction(action, playback) {
  if (playback === 'once') {
    action.setLoop(THREE.LoopOnce, 1);
    action.clampWhenFinished = true;
  } else {
    action.setLoop(THREE.LoopRepeat, Infinity);
    action.clampWhenFinished = false;
  }
  return action;
}

/**
 * @param {THREE.AnimationAction | null} previous
 * @param {THREE.AnimationAction} next
 * @param {number} duration
 */
export function crossFadeAnimationActions(previous, next, duration) {
  previous?.fadeOut(duration);
  next.setEffectiveWeight(1).fadeIn(duration).play();
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { getAgentBusApi } from '../lib/desktopMode';

/**
 * The window's half of the local agent bus (Refs #6).
 *
 * Three one-way hops, no request/response channel: this reports what is on
 * stage, the main process validates an incoming request against that report
 * and answers the caller itself, and whatever it accepted comes back here to
 * be applied. Acceptance happens in main, application happens here — which is
 * why a 200 means "accepted", not "the model has finished loading".
 *
 * Desktop only: `getAgentBusApi()` is null in the browser build and every
 * effect below turns into a no-op.
 *
 * @param {Object} args
 * @param {import('../config/agentBus').AgentBusSettings} args.settings
 * @param {{ context: unknown, state: unknown }} args.snapshot What the bus may
 * be asked for, and what it is allowed to ask for.
 * @param {(action: import('../lib/stageCommands').StageAction) => void} args.applyAction
 * @param {boolean} args.ready False until config.yaml has been read — starting
 * the server before that would bind the default port, then rebind to the
 * user's.
 */
export function useAgentBus({ settings, snapshot, applyAction, ready }) {
  const api = useMemo(() => getAgentBusApi(), []);
  const [status, setStatus] = useState(null);

  // The listener is registered once; keeping the callback in a ref means a
  // re-render cannot drop an action arriving mid-swap.
  const applyRef = useRef(applyAction);
  useEffect(() => {
    applyRef.current = applyAction;
  }, [applyAction]);

  const { enabled, port, requireToken } = settings;

  useEffect(() => {
    if (!api || !ready) return undefined;

    let cancelled = false;
    void api
      .configure({ enabled, port, requireToken })
      .then((next) => {
        if (!cancelled) setStatus(next);
      })
      .catch(() => {
        if (!cancelled) setStatus(null);
      });

    return () => {
      cancelled = true;
    };
  }, [api, ready, enabled, port, requireToken]);

  // Every change to the catalog or the selection, whatever caused it. Until
  // the first one lands, the bus answers 503 rather than guessing — which is
  // also why `enabled` is a dependency and not just a guard: switching the bus
  // on has to send the report the running server is about to need.
  useEffect(() => {
    if (!api || !enabled) return;
    api.report(snapshot);
  }, [api, enabled, snapshot]);

  useEffect(() => {
    if (!api?.onAction) return undefined;
    return api.onAction((action) => applyRef.current?.(action));
  }, [api]);

  const rotateToken = useCallback(async () => {
    if (!api?.rotateToken) return null;
    const next = await api.rotateToken();
    setStatus(next);
    return next;
  }, [api]);

  return { status, rotateToken };
}

/**
 * The user-visible half of the local agent bus (Refs #6), free of asset imports
 * so `node --test` can load it.
 *
 * The token is deliberately absent: `config.yaml` is a snapshot of live stage
 * state, rewritten by the renderer on every change, while the token has to be
 * readable by the main process before a window exists. It lives encrypted
 * beside the VRoid Hub credentials instead — see electron/agent-bus-token.cjs.
 */

/** Keep in step with DEFAULT_AGENT_BUS_PORT in electron/agent-bus.cjs. */
export const defaultAgentBusPort = 47903;

const MIN_PORT = 1024;
const MAX_PORT = 65535;

/** @typedef {{ enabled: boolean, port: number, requireToken: boolean }} AgentBusSettings */

/** @returns {AgentBusSettings} */
export function createDefaultAgentBus() {
  return { enabled: false, port: defaultAgentBusPort, requireToken: true };
}

/** @param {unknown} value */
export function normalizeAgentBusPort(value) {
  const port = Number(value);
  if (!Number.isInteger(port) || port < MIN_PORT || port > MAX_PORT) return defaultAgentBusPort;
  return port;
}

/**
 * @param {unknown} raw
 * @returns {AgentBusSettings}
 */
export function normalizeAgentBus(raw) {
  const defaults = createDefaultAgentBus();
  if (!raw || typeof raw !== 'object') return defaults;

  const data = /** @type {Record<string, unknown>} */ (raw);
  return {
    // Opt-in: an absent or malformed section leaves the bus off.
    enabled: data.enabled === true,
    port: normalizeAgentBusPort(data.port),
    // Only an explicit false turns the token off, so a hand-edited file that
    // drops the key stays authenticated.
    requireToken: data.requireToken !== false,
  };
}

import { useEffect, useState } from 'react';
import { normalizeAgentBusPort } from '../../config/agentBus';

/**
 * Settings → Agents: the opt-in for the local agent bus (Refs #6).
 *
 * @param {{
 *   settings: import('../../config/agentBus').AgentBusSettings,
 *   status: {
 *     running: boolean, token: string | null,
 *     tokenPersisted: boolean, error: string | null,
 *   } | null,
 *   onChange: (next: import('../../config/agentBus').AgentBusSettings) => void,
 *   onRotateToken: () => Promise<unknown>,
 * }} props
 */
export function AgentBusPanel({ settings, status, onChange, onRotateToken }) {
  // Held as text while it is being typed: the server only rebinds once the
  // field is committed, not on every keystroke.
  const [portDraft, setPortDraft] = useState(String(settings.port));
  const [copied, setCopied] = useState(null);

  useEffect(() => {
    setPortDraft(String(settings.port));
  }, [settings.port]);

  useEffect(() => {
    if (!copied) return undefined;
    const timer = window.setTimeout(() => setCopied(null), 1600);
    return () => window.clearTimeout(timer);
  }, [copied]);

  const token = status?.token ?? null;
  const example = [
    `curl -X POST http://127.0.0.1:${settings.port}/v1/command \\`,
    '  -H "Content-Type: application/json" \\',
    ...(settings.requireToken ? [`  -H "Authorization: Bearer ${token ?? '<token>'}" \\`] : []),
    // Without a mode this would *select* the clip and persist it, so the
    // example that gets copied is the one an agent almost always wants.
    `  -d '{"command":"animation.play","payload":{"id":"Peace Sign","mode":"once"}}'`,
  ].join('\n');

  // The endpoint, not a registration command for one particular client: every
  // MCP client spells that differently, and the two values they all need — this
  // URL and, when it is on, the token above — are the two this panel owns
  // (Refs #61).
  const mcpUrl = `http://127.0.0.1:${settings.port}/mcp`;

  async function copy(what, text) {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(what);
    } catch {
      setCopied(null);
    }
  }

  function commitPort() {
    const next = normalizeAgentBusPort(portDraft);
    setPortDraft(String(next));
    if (next !== settings.port) onChange({ ...settings, port: next });
  }

  return (
    <div className="agent-bus-panel">
      <p className="panel-note panel-note--compact">
        Lets local scripts and agents play animations, swap avatars and set the environment over
        127.0.0.1 — the same commands the menus and hotkeys use. Nothing outside this machine can
        reach it.
      </p>

      <div className="desktop-toggle-row">
        <span className="settings-section-title">Enable local bus</span>
        <input
          type="checkbox"
          className="panel-checkbox"
          checked={settings.enabled}
          onChange={() => onChange({ ...settings, enabled: !settings.enabled })}
        />
      </div>

      <p className="panel-note panel-note--compact">{describe(settings, status)}</p>

      <label className="field-label" htmlFor="agent-bus-port">
        Port
      </label>
      <input
        id="agent-bus-port"
        className="field-input"
        type="number"
        min={1024}
        max={65535}
        value={portDraft}
        onChange={(event) => setPortDraft(event.target.value)}
        onBlur={commitPort}
        onKeyDown={(event) => {
          if (event.key === 'Enter') event.currentTarget.blur();
        }}
      />

      <div className="desktop-toggle-row">
        <span className="settings-section-title">Require token</span>
        <input
          type="checkbox"
          className="panel-checkbox"
          checked={settings.requireToken}
          onChange={() => onChange({ ...settings, requireToken: !settings.requireToken })}
        />
      </div>

      {settings.requireToken ? (
        <>
          {token ? (
            <p className="panel-note--mono agent-bus-panel__value">{token}</p>
          ) : (
            <p className="panel-note panel-note--compact">Generated when you enable the bus.</p>
          )}
          {status && !status.tokenPersisted && (
            <p className="panel-note panel-note--compact">
              No OS keychain available, so this token is kept in memory and changes every launch.
            </p>
          )}
          <div className="panel-actions">
            <button
              type="button"
              className="panel-button"
              disabled={!token}
              onClick={() => void copy('token', token ?? '')}
            >
              {copied === 'token' ? 'Copied' : 'Copy token'}
            </button>
            <button
              type="button"
              className="panel-button panel-button--danger"
              onClick={() => void onRotateToken()}
            >
              Regenerate
            </button>
          </div>
        </>
      ) : (
        <p className="panel-note panel-note--compact">
          Anything on this machine can drive the avatar while the bus is on.
        </p>
      )}

      <p className="panel-note panel-note--compact">
        The MCP endpoint, for an agent in your editor. Same server as the curl below
        {settings.requireToken ? ', behind the same token' : ''} — it answers only while AVATAR is
        running.
      </p>

      <p className="panel-note--mono agent-bus-panel__value">{mcpUrl}</p>

      {/* Stacked rather than side by side: "Copy example curl" wraps inside a
          half-width button in a drawer this narrow, and the label is worth more
          than the row. */}
      <div className="panel-actions panel-actions--wide">
        <button type="button" className="panel-button" onClick={() => void copy('mcp', mcpUrl)}>
          {copied === 'mcp' ? 'Copied' : 'Copy MCP URL'}
        </button>
        <button type="button" className="panel-button" onClick={() => void copy('curl', example)}>
          {copied === 'curl' ? 'Copied' : 'Copy example curl'}
        </button>
      </div>
    </div>
  );
}

/**
 * @param {import('../../config/agentBus').AgentBusSettings} settings
 * @param {{ running: boolean, error: string | null } | null} status
 */
function describe(settings, status) {
  if (!settings.enabled) return 'Off. Nothing is listening.';
  // A port that is already taken is not worked around: the copied curl above
  // names a port, and moving would make it point at the wrong one.
  if (status?.error) return status.error;
  if (!status?.running) return 'Starting…';
  // Just the address: the routes would wrap to three lines in a column this
  // narrow, and Copy example curl hands over a working one anyway.
  return `Listening on 127.0.0.1:${settings.port}.`;
}
